INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(11490, 'plPL', 'Wróżebna kula Widzącego', '<Tyrith krzywi się z bólu, mówiąc.>$b$bIdź na taras... użyj kuli.$b$b...Oni... karmią Słoneczną Studnię...$b$b<Tyrith łapie powietrze.>$b$bPośpiesz się... Trzeba ich powstrzymać... zanim zdołają...$b$b<Tyrith umiera.>', 'Tyrith chce, żebyś $gużył:użyła; kuli na balkonie Tarasu Magistrów.', '', 'Wróć do Kalegosa na Tarasie Magistrów.', 'Wróżebna kula uruchomiona', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(11490, 'plPL', 'Nie uważam za przypadek, że nasze ścieżki skrzyżowały się właśnie dziś.$b$bWyczuwam macki przeznaczenia...', 0);
