INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(23752, 'plPL', 'Vexallus wyładowuje czystą energię!', '', 0),
(23753, 'plPL', '%s zaczyna czerpać moc z pobliskiego Kryształu spaczenia. Zniszcz go!', '', 0),
(23781, 'plPL', 'Vexallus się przeciąża!', '', 0),
(23840, 'plPL', 'Moc! Więcej, więcej, więcej!', '', 0),
(23841, 'plPL', 'Kipi i pali...', '', 0),
(23842, 'plPL', 'Nigdy nie przestanę. Nigdy...', '', 0),
(23845, 'plPL', 'Jest MOJA!', '', 0),
(23847, 'plPL', 'Precz od moich kryształów!', '', 0),
(25386, 'plPL', 'Nie róbcie takich zadowolonych min! Wiem, co sobie myślicie, ale Twierdza Burz była tylko chwilowym niepowodzeniem. Naprawdę sądziliście, że powierzyłbym przyszłość jakiemuś ślepemu kundlowi, pół-nocnemu elfowi?', '', 0),
(25387, 'plPL', 'O nie, był tylko narzędziem, stopniem do znacznie większego planu! Wszystko prowadziło do tej chwili... i tym razem nie przeszkodzicie!', '', 0),
(25388, 'plPL', 'Zemsta płonie!', '', 0),
(25389, 'plPL', 'Felomin Ashal!', '', 0),
(25390, 'plPL', 'Wywrócę wasz świat... do góry... nogami.', '', 0),
(25391, 'plPL', 'Mistrzu, daj mi siłę.', '', 0),
(25392, 'plPL', 'Nie czujcie się... zbyt swobodnie.', '', 0),
(25393, 'plPL', 'Moja śmierć niczego nie zmieni! Mistrz was dopadnie! Utoniecie we własnej krwi! Świat spłonie! Aaach!', '', 0),
(25423, 'plPL', 'Tylko marnujecie mój czas!', '', 0),
(25424, 'plPL', 'Mój głód nie zna granic!', '', 0),
(25425, 'plPL', 'Tak!! Jestem bogiem!', '', 0),
(25426, 'plPL', 'Nie... więcej, muszę mieć więcej!!', '', 0),
(25428, 'plPL', 'Dość tego rozpraszania!', '', 0),
(25430, 'plPL', '', 'Unicestwić ich.', 0),
(25431, 'plPL', '', 'Nie tak to... planowałam.', 0),
(25432, 'plPL', '', 'Och, cóż za okropność!', 0),
(25433, 'plPL', '', 'No proszę, ale z ciebie $gszczęściarz:szczęściara;, co?', 0),
(25434, 'plPL', '', 'Teraz zaczynam się irytować.', 0),
(25435, 'plPL', '', 'Do diabła ze sługami! Sama cię wykończę!', 0),
(25436, 'plPL', '', 'To ja nazywam dobrym początkiem.', 0),
(25437, 'plPL', '', 'Mogłabym przysiąc, że było was więcej...', 0),
(25438, 'plPL', '', 'To już niezbyt „drużyna”, prawda?', 0),
(25439, 'plPL', '', 'Jedynka to taka samotna liczba.', 0),
(25440, 'plPL', '', 'Było naprawdę zabawnie.', 0),
(25623, 'plPL', 'Wyssać... życie!', '', 0),
(25625, 'plPL', 'Uwol...nić.', '', 0),
(25626, 'plPL', 'Nie do...o...pa...nowania.', '', 0),
(25627, 'plPL', 'Po...chłonąć.', '', 0),
(34142, 'plPL', 'Jestem niezwyciężony!', '', 0);
